package com.qiban.companion;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;
import android.util.Base64;

final class NetworkBroker {
    interface Events { void send(JSONObject event)throws Exception; }
    private final ArchiveStore store;private final SecretVault vault;
    private final ConcurrentMap<String,HttpURLConnection> connections=new ConcurrentHashMap<>();
    NetworkBroker(ArchiveStore s,SecretVault v){store=s;vault=v;}
    static String endpoint(String address,String path)throws Exception {URI u=URI.create(address.trim());if(!"https".equalsIgnoreCase(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null)throw new IOException("接口请使用 HTTPS，密钥单独填写。");String value=address.replaceAll("/+$","");if(u.getPath().isEmpty())return value+"/v1/"+path;if(u.getPath().equals("/v1")||u.getPath().endsWith("/v1"))return value+"/"+path;return value;}
    String mainURL()throws Exception{return endpoint(store.settings().getString("endpoint"),"chat/completions");}
    JSONObject service(String name)throws Exception{JSONObject all=store.settings().optJSONObject("services");return all==null?null:all.optJSONObject(name);}
    String serviceURL(JSONObject profile)throws Exception {String proto=profile.optString("apiProtocol"),path=switch(proto){case "deepSeekSearch"->"tools/search";case "deepSeekTTS"->"tools/tts";case "openAISpeech"->"audio/speech";case "deepSeekASR"->"tools/asr";case "openAITranscription"->"audio/transcriptions";default->"chat/completions";};return endpoint(profile.optString("endpoint"),path);}
    String key(JSONObject service)throws Exception{return vault.get("service:"+service.optString("apiProtocol")+"|"+serviceURL(service));}
    JSONObject complete(JSONArray messages,JSONObject service)throws Exception {JSONObject settings=store.settings();String url=service==null?mainURL():serviceURL(service),key=service==null?vault.get("main:"+url):key(service);String model=service==null?settings.optString("model"):service.optString("model");if(model.isEmpty())throw new IOException("请先填写模型名称。");JSONObject body=new JSONObject().put("model",model).put("stream",false).put("temperature",settings.optDouble("temperature",.7)).put("messages",messages);return new JSONObject(new String(exchange(url,Map.of("Authorization","Bearer "+key,"Content-Type","application/json"),body.toString().getBytes(StandardCharsets.UTF_8),"POST",2*1024*1024),StandardCharsets.UTF_8));}
    static String reply(JSONObject response)throws Exception {JSONArray choices=response.optJSONArray("choices");if(choices==null||choices.length()==0)throw new IOException("接口没有返回回复。");Object content=choices.getJSONObject(0).getJSONObject("message").get("content");if(content instanceof String)return(String)content;if(content instanceof JSONArray){StringBuilder result=new StringBuilder();JSONArray a=(JSONArray)content;for(int i=0;i<a.length();i++)result.append(a.getJSONObject(i).optString("text"));return result.toString();}throw new IOException("回复格式不支持。");}
    JSONArray search(String query)throws Exception {JSONObject p=service("search");if(p==null||!p.optBoolean("enabled"))throw new IOException("请先在独立接口里启用搜索。");String q=query.substring(0,Math.min(128,query.length()));byte[] result=exchange(serviceURL(p),Map.of("Authorization","Bearer "+key(p),"Content-Type","application/json"),new JSONObject().put("query",q).toString().getBytes(StandardCharsets.UTF_8),"POST",512*1024);JSONObject object=new JSONObject(new String(result,StandardCharsets.UTF_8));JSONArray rows=object.optJSONArray("results");if(rows==null&&object.optJSONObject("data")!=null)rows=object.getJSONObject("data").optJSONArray("results");if(rows==null)throw new IOException("搜索接口返回格式无效。");JSONArray out=new JSONArray();for(int i=0;i<Math.min(rows.length(),5);i++){JSONObject r=rows.getJSONObject(i);String address=r.optString("url");URI u=URI.create(address);if(!List.of("http","https").contains(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null)continue;out.put(new JSONObject().put("title",r.optString("title")).put("url",address).put("summary",r.optString("summary",r.optString("snippet"))));}return out;}
    byte[] speech(JSONObject p,String text,float speed)throws Exception {boolean deep=p.optString("apiProtocol").equals("deepSeekTTS");JSONObject body=deep?new JSONObject().put("text",text).put("voice_id",p.optString("voice")).put("format","wav").put("filter_markdown",true):new JSONObject().put("model",p.optString("model")).put("input",text).put("voice",p.optString("voice")).put("response_format","wav").put("speed",speed);return exchange(serviceURL(p),Map.of("Authorization","Bearer "+key(p),"Content-Type","application/json"),body.toString().getBytes(StandardCharsets.UTF_8),"POST",12*1024*1024);}
    private HttpURLConnection connection(String address,String method,Map<String,String> headers)throws Exception {URI u=URI.create(address);if(!List.of("http","https").contains(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getFragment()!=null||address.length()>4096)throw new IOException("网络地址无效。");HttpURLConnection c=(HttpURLConnection)u.toURL().openConnection();c.setConnectTimeout(15000);c.setReadTimeout(120000);c.setUseCaches(false);c.setInstanceFollowRedirects(false);c.setRequestMethod(method);for(var e:headers.entrySet()){String k=e.getKey(),v=vault.header(e.getValue(),address);if(k.contains("\r")||k.contains("\n")||v.contains("\r")||v.contains("\n"))throw new IOException("请求头无效。");if(!List.of("host","connection","content-length","accept-encoding").contains(k.toLowerCase(Locale.ROOT)))c.setRequestProperty(k,v);}return c;}
    byte[] exchange(String address,Map<String,String> headers,byte[] body,String method,int max)throws Exception {HttpURLConnection c=connection(address,method,headers);try{write(c,body);int status=c.getResponseCode();if(status>=300&&status<400)throw new IOException("接口发生重定向，请填写最终地址。");InputStream input=status<400?c.getInputStream():c.getErrorStream();if(input==null)throw new IOException("接口没有返回数据。");try(input){byte[] data=FilesSupportBytes.read(input,max+1);if(data.length>max)throw new IOException("接口响应超过大小上限。");if(status>=400)throw new IOException("接口返回 HTTP "+status+"："+new String(data,StandardCharsets.UTF_8).substring(0,Math.min(300,new String(data,StandardCharsets.UTF_8).length())));return data;}}finally{c.disconnect();}}
    private static void write(HttpURLConnection c,byte[] body)throws Exception {if(body!=null&&body.length>0){if(body.length>32*1024*1024)throw new IOException("单次上传超过32MB。");c.setDoOutput(true);c.setFixedLengthStreamingMode(body.length);try(OutputStream out=c.getOutputStream()){out.write(body);}}}
    void fetch(JSONObject input,Events events)throws Exception {
        String id=input.getString("id"),url=input.getString("url"),method=input.optString("method","GET");Map<String,String> headers=new HashMap<>();JSONObject h=input.optJSONObject("headers");if(h!=null){Iterator<String> keys=h.keys();while(keys.hasNext()){String k=keys.next();headers.put(k,h.getString(k));}}byte[] body=Base64.decode(input.optString("body"),Base64.DEFAULT);URI uri=URI.create(url);
        if("qiban.app".equals(uri.getHost())){
            if(uri.getPath().endsWith("/tools/search")){byte[] data=new JSONObject().put("results",search(new JSONObject(new String(body,StandardCharsets.UTF_8)).optString("query"))).toString().getBytes(StandardCharsets.UTF_8);events.send(new JSONObject().put("type","fetchHeaders").put("id",id).put("status",200).put("headers",new JSONObject().put("content-type","application/json")));events.send(new JSONObject().put("type","fetchChunk").put("id",id).put("data",Base64.encodeToString(data,Base64.NO_WRAP)));events.send(new JSONObject().put("type","fetchEnd").put("id",id));return;}
            if(!uri.getPath().endsWith("/chat/completions"))throw new IOException("此功能请配置对应的远程接口。");JSONObject p=uri.getPath().startsWith("/vision/")?service("vision"):null;if(p!=null&&!p.optBoolean("enabled"))p=null;url=p==null?mainURL():serviceURL(p);JSONObject data=new JSONObject(new String(body,StandardCharsets.UTF_8));data.put("model",p==null?store.settings().optString("model"):p.optString("model"));body=data.toString().getBytes(StandardCharsets.UTF_8);headers.entrySet().removeIf(e->List.of("authorization","api-key","x-api-key").contains(e.getKey().toLowerCase(Locale.ROOT)));headers.put("Authorization","Bearer "+(p==null?vault.get("main:"+url):key(p)));
        }
        if(connections.size()>=12)throw new IOException("当前网络任务过多。");HttpURLConnection c=connection(url,method,headers);connections.put(id,c);try{write(c,body);int status=c.getResponseCode();if(status>=300&&status<400)throw new IOException("接口发生重定向，请填写最终地址。");JSONObject responseHeaders=new JSONObject();for(var e:c.getHeaderFields().entrySet()){if(e.getKey()==null)continue;String k=e.getKey().toLowerCase(Locale.ROOT);if(!List.of("set-cookie","connection","content-length","content-encoding").contains(k))responseHeaders.put(k,String.join(",",e.getValue()));}boolean sse=responseHeaders.optString("content-type").contains("text/event-stream");events.send(new JSONObject().put("type","fetchHeaders").put("id",id).put("status",status).put("headers",responseHeaders));InputStream stream=status<400?c.getInputStream():c.getErrorStream();if(stream==null)stream=new ByteArrayInputStream(new byte[0]);int total=0,max=sse?64*1024*1024:32*1024*1024;try(InputStream in=new BufferedInputStream(stream)){ByteArrayOutputStream chunk=new ByteArrayOutputStream();int b,tail=0;while((b=in.read())!=-1){if(Thread.currentThread().isInterrupted()||!connections.containsKey(id))throw new InterruptedException();chunk.write(b);if(++total>max)throw new IOException("接口响应达到大小上限。");tail=(tail<<8)|b;if(chunk.size()>=65536||sse&&((tail&65535)==0x0a0a||tail==0x0d0a0d0a)){events.send(new JSONObject().put("type","fetchChunk").put("id",id).put("data",Base64.encodeToString(chunk.toByteArray(),Base64.NO_WRAP)));chunk.reset();}}if(chunk.size()>0)events.send(new JSONObject().put("type","fetchChunk").put("id",id).put("data",Base64.encodeToString(chunk.toByteArray(),Base64.NO_WRAP)));}events.send(new JSONObject().put("type","fetchEnd").put("id",id));}finally{connections.remove(id);c.disconnect();}
    }
    void abort(String id){HttpURLConnection c=connections.remove(id);if(c!=null)c.disconnect();}
    void cancelAll(){for(String id:connections.keySet())abort(id);}
}
